mapper.select:
SELECT LAST(ts) AS ts, vin, current_fuel_level, current_battery_level, ROUND(accumulated_mileage,2) AS accumulatedMileage FROM unmanned_car_status
vin = #{vin}
GROUP BY vin

SELECT LAST(ts) AS ts, vin, power_on_status, control_model, power_mode, charge_status, lamp_switch_status, battery, current_fuel_level, current_battery_level, ROUND(accumulated_mileage,2) AS accumulatedMileage FROM unmanned_car_status
AND ts >= #{startTime}
AND ts < #{endTime}
GROUP BY vin
